<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/bootstrap.php';   // sesi aman + login
require_once __DIR__ . '/project-manager.php';
if (empty($_SESSION['cms_csrf'])) $_SESSION['cms_csrf'] = bin2hex(random_bytes(24));
$error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    try {
        if (!hash_equals((string) $_SESSION['cms_csrf'], (string) ($_POST['csrf'] ?? ''))) throw new RuntimeException('Sesi formulir tidak valid.');
        if (($_POST['action'] ?? 'register') !== 'select') cmsRequireAdmin('Menambah, menghapus, atau memasang asset project');
        if (($_POST['action'] ?? '') === 'select') {
            $id = (string) ($_POST['project_id'] ?? '');
            $registry = projectRegistry();
            if (!isset($registry[$id]) || !cmsCanAccessProject($id)) throw new RuntimeException('Project tidak ditemukan.');
            $assetsDirectory = projectRuntimeDirectory($registry[$id]);
            if (!is_file($assetsDirectory . '/global-database.js')) throw new RuntimeException('Project belum memiliki asset CMS. Gunakan tombol Terapkan asset pada kartu project.');
        } elseif (($_POST['action'] ?? '') === 'install_assets') {
            $id = (string) ($_POST['project_id'] ?? '');
            $result = installProjectAssets($id, (string) ($_POST['asset_strategy'] ?? ''));
            $_SESSION['cms_flash'] = !empty($result['adopted']) ? 'Folder ' . $result['directory'] . ' yang sudah ada kini dipakai CMS. Tidak ada file yang disalin atau dihapus.' : 'Template assets diterapkan ke ' . $result['directory'] . ' (' . $result['files'] . ' file).' . ($result['archived'] !== '' ? ' Asset lama disimpan sebagai ' . $result['archived'] . '.' : '');
            header('Location: projects.php'); exit;
        } elseif (($_POST['action'] ?? '') === 'remove') {
            $id = (string) ($_POST['project_id'] ?? '');
            removeProject($id);
            header('Location: projects.php'); exit;
        } else {
            $id = registerProject((string) ($_POST['project_name'] ?? ''), (string) ($_POST['project_path'] ?? ''));
            header('Location: projects.php?setup=' . rawurlencode($id)); exit;
        }
        $_SESSION['cms_project'] = $id;
        header('Location: index.php?project=' . rawurlencode($id)); exit;
    } catch (Throwable $exception) { $error = $exception->getMessage(); }
}
$projects = array_filter(projectRegistry(), static fn($p, $k) => cmsCanAccessProject((string) $k), ARRAY_FILTER_USE_BOTH); $discovered = cmsIsAdmin() ? discoverProjects() : []; $me = cmsCurrentUser(); $flash = (string) ($_SESSION['cms_flash'] ?? ''); unset($_SESSION['cms_flash']);
function e(mixed $value): string { return htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8'); }
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pilih Project — CMS Virtual Tour</title><link rel="stylesheet" href="style.css?v=<?= e((string) filemtime(__DIR__ . '/style.css')) ?>"><link rel="stylesheet" href="assets/css/auth.css?v=<?= e((string) filemtime(__DIR__ . '/assets/css/auth.css')) ?>"></head>
<body class="project-picker-page"><main class="project-picker-shell">
<header class="project-picker-header"><div><span class="eyebrow">GOVIRTUAL CMS</span><h1>Mau kelola project yang mana?</h1><p>Pilih project untuk membuka dashboard, atau buat project baru dalam beberapa klik.</p></div><span class="project-count"><?= count($projects) ?> project</span><nav class="cms-userbar" aria-label="Akun"><span class="cms-userbar__who"><b><?= e($me['name'] ?? $me['username']) ?></b><small><?= e(CMS_ROLES[$me['role']] ?? $me['role']) ?></small></span><a href="users.php"><?= cmsIsAdmin() ? 'Pengguna' : 'Akun saya' ?></a><a href="logout.php">Keluar</a></nav></header>
<?php if (!$projects): ?><div class="alert error">Akun Anda belum diberi akses ke project mana pun. Hubungi admin CMS.</div><?php endif; ?>
<?php if ($error !== ''): ?><div class="alert error"><?= e($error) ?></div><?php endif; ?>
<?php if ($flash !== ''): ?><div class="alert success"><?= e($flash) ?></div><?php endif; ?>
<section class="project-grid">
<?php foreach ($projects as $id => $project): $assetName = trim((string) ($project['assets_dir'] ?? '')); $assetBase = rtrim((string) $project['path'], '/\\') . '/' . $assetName; $assetReady = $assetName !== '' && projectAssetsValid($assetBase); $folderOk = is_dir((string) $project['path']); $existingValid = $folderOk && projectAssetsValid(rtrim((string) $project['path'], '/') . '/assets'); ?><article class="project-card"><div class="project-card-top"><span class="project-folder-icon">📁</span><span class="project-ready <?= $assetReady ? '' : 'needs-setup' ?>"><i></i> <?= !$folderOk ? 'Folder tidak ada di server ini' : ($assetReady ? 'Siap dikelola' : ($existingValid ? 'Assets ditemukan' : 'Asset belum disiapkan')) ?></span></div><div class="project-card-copy"><strong><?= e($project['name']) ?></strong><small><?= e(basename((string) $project['path'])) ?></small><em><?= !$folderOk ? e((string) $project['path']) : ($assetReady ? 'Asset aktif · ' . e($assetName) : ($existingValid ? 'Folder assets sudah lengkap, cukup dipakai' : 'Perlu template assets')) ?></em></div><div class="project-card-actions"><?php if ($assetReady): ?><form method="post"><input type="hidden" name="csrf" value="<?= e($_SESSION['cms_csrf']) ?>"><input type="hidden" name="action" value="select"><input type="hidden" name="project_id" value="<?= e($id) ?>"><button class="project-open" type="submit"><span>Buka dashboard</span><b>→</b></button></form><?php elseif (cmsIsAdmin() && $folderOk): ?><button type="button" class="project-open" data-install-assets="<?= e($id) ?>" data-assets-valid="<?= $existingValid ? '1' : '0' ?>" data-assets-exist="<?= is_dir(rtrim((string) $project['path'], '/\\') . '/assets') ? '1' : '0' ?>"><span><?= $existingValid ? 'Pakai assets yang ada' : 'Terapkan asset' ?></span><b><?= $existingValid ? '✓' : '＋' ?></b></button><?php endif; ?><?php if (!$assetReady && $folderOk): ?><a class="project-open" style="flex:0 0 auto;text-decoration:none" href="index.php?project=<?= e($id) ?>&amp;tab=loading" title="Optimasi loading &amp; Smart Hub tidak memerlukan assets CMS"><span>⚡ Optimasi</span></a><?php endif; ?><?php if (cmsIsAdmin()): ?><form method="post" data-remove-project><input type="hidden" name="csrf" value="<?= e($_SESSION['cms_csrf']) ?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="project_id" value="<?= e($id) ?>"><button class="project-remove" type="submit" title="Hapus dari CMS" aria-label="Hapus <?= e($project['name']) ?> dari CMS">×</button></form><?php endif; ?></div></article><?php endforeach; ?>
<?php if (cmsIsAdmin()): ?><button type="button" class="project-add-card" id="openProjectCreator"><span class="project-add-icon">＋</span><strong>Tambah project baru</strong><small>Hubungkan folder virtual tour lainnya</small></button><?php endif; ?>
</section>
<footer class="project-picker-footer"><span>Folder project</span><code><?= e(cmsBaseDirectory()) ?></code></footer>
</main>
<div class="project-create-modal <?= $error !== '' ? 'open' : '' ?>" id="projectCreateModal" aria-hidden="<?= $error !== '' ? 'false' : 'true' ?>"><div class="project-create-backdrop" data-close-project-creator></div><section class="project-create-dialog" role="dialog" aria-modal="true" aria-labelledby="projectCreateTitle"><header><div><span>＋</span><div><h2 id="projectCreateTitle">Tambah project baru</h2><p>Pilih folder yang berisi hasil virtual tour.</p></div></div><button type="button" data-close-project-creator aria-label="Tutup">×</button></header><form method="post"><input type="hidden" name="csrf" value="<?= e($_SESSION['cms_csrf']) ?>"><input type="hidden" name="action" value="register"><label><span>Nama project <small>opsional</small></span><input name="project_name" placeholder="Contoh: Bali Virtual Tour"></label><label><span>Folder project</span><select name="project_path" required><option value="">— Pilih folder yang terdeteksi —</option><?php foreach ($discovered as $folder): if ($folder['registered']) continue; ?><option value="<?= e($folder['path']) ?>"><?= e($folder['name']) ?> · <?= e(basename((string) $folder['path'])) ?></option><?php endforeach; ?></select><small class="field-help">Hanya folder dengan struktur virtual tour yang ditampilkan.</small></label><div class="project-create-actions"><button type="button" data-close-project-creator>Batal</button><button class="save" type="submit">Buat &amp; buka project</button></div></form></section></div>
<div class="project-create-modal" id="assetInstallModal" aria-hidden="true"><div class="project-create-backdrop" data-close-asset-install></div><section class="project-create-dialog asset-install-dialog" role="dialog" aria-modal="true"><header><div><span>📦</span><div><h2>Terapkan template asset</h2><p id="assetInstallMessage">Salin template dari Jakarta ke project ini.</p></div></div><button type="button" data-close-asset-install>×</button></header><form method="post"><input type="hidden" name="csrf" value="<?= e($_SESSION['cms_csrf']) ?>"><input type="hidden" name="action" value="install_assets"><input type="hidden" name="project_id" id="assetInstallProject"><div class="asset-strategy-list"><label><input type="radio" name="asset_strategy" value="adopt"><span><strong>Pakai assets yang sudah ada (disarankan)</strong><small>Folder assets project ini sudah lengkap. Tidak ada file yang disalin, diganti, atau dihapus.</small></span></label><label><input type="radio" name="asset_strategy" value="create"><span><strong>Buat folder assets</strong><small>Gunakan jika project belum memiliki folder assets.</small></span></label><label><input type="radio" name="asset_strategy" value="archive"><span><strong>Arsipkan assets lama</strong><small>Ubah assets menjadi assets-old, lalu template baru menjadi assets.</small></span></label><label><input type="radio" name="asset_strategy" value="replace"><span><strong>Replace assets lama</strong><small>HAPUS folder asset aktif lalu salin template. Data lokasi di folder lama hilang.</small></span></label><label><input type="radio" name="asset_strategy" value="alternate"><span><strong>Buat assets-2</strong><small>Asset lama aman; CMS memakai folder baru.</small></span></label></div><div class="project-create-actions"><button type="button" data-close-asset-install>Cancel</button><button class="save" type="submit">Terapkan asset</button></div></form></section></div>
<script>(()=>{const modal=document.getElementById('projectCreateModal'),assetModal=document.getElementById('assetInstallModal');const show=element=>{element.classList.add('open');element.setAttribute('aria-hidden','false');document.body.classList.add('modal-open')};const hide=element=>{element.classList.remove('open');element.setAttribute('aria-hidden','true');document.body.classList.remove('modal-open')};document.getElementById('openProjectCreator')?.addEventListener('click',()=>{show(modal);setTimeout(()=>modal.querySelector('select').focus(),50)});modal.querySelectorAll('[data-close-project-creator]').forEach(item=>item.addEventListener('click',()=>hide(modal)));document.querySelectorAll('[data-install-assets]').forEach(button=>button.addEventListener('click',()=>{document.getElementById('assetInstallProject').value=button.dataset.installAssets;const exists=button.dataset.assetsExist==='1',valid=button.dataset.assetsValid==='1';assetModal.querySelector('[value="adopt"]').closest('label').hidden=!valid;assetModal.querySelector('[value="create"]').closest('label').hidden=exists;assetModal.querySelector('[value="archive"]').closest('label').hidden=!exists;assetModal.querySelector('[value="replace"]').closest('label').hidden=!exists;assetModal.querySelector('[value="create"]').checked=!exists;assetModal.querySelector('[value="archive"]').checked=exists&&!valid;assetModal.querySelector('[value="adopt"]').checked=valid;document.getElementById('assetInstallMessage').textContent=valid?'Folder assets project ini sudah lengkap. Pilih "Pakai assets yang sudah ada": aman, tidak ada file yang berubah.':exists?'Folder assets sudah ada. Pilih Cancel, arsipkan, replace, atau buat assets-2.':'Project belum memiliki assets. Template akan disalin dari project acuan.';show(assetModal)}));assetModal.querySelectorAll('[data-close-asset-install]').forEach(item=>item.addEventListener('click',()=>hide(assetModal)));document.querySelectorAll('[data-remove-project]').forEach(form=>form.addEventListener('submit',event=>{if(!confirm('Hapus project ini dari daftar CMS? Folder dan seluruh file project asli tidak akan dihapus.'))event.preventDefault()}));document.addEventListener('keydown',event=>{if(event.key==='Escape'){hide(modal);hide(assetModal)}});})();</script>
</body></html>
